(function(){
'use strict';
const {questions,categories,sources}=window.PRACTICE_BANK;
const githubBrief={verbal:'主旨 · 细节 · 推断 · 语句排序',quantity:'比例 · 工程 · 概率 · 人数约束',sequence:'分组 · 交叉 · 幂次 · 差分',data:'增长率 · 占比 · 总量 · 图表比较',logic:'条件推理 · 论证 · 排列 · 结构',figure:'旋转 · 数量 · 叠加 · 位置',spatial:'平面拼合 · 翻折变换（2 题）'};
const {selectQuestions,assess}=window.PRACTICE_ENGINE;
const app=document.getElementById('app');
let view='home',config={mode:'instant',category:'all',count:'14',difficulty:'',provenance:'github',minutes:14};
let session=null,report=null,reportSession=null,wrongIds=new Set(),wrongAnswers=new Map(),search='',sourceCategory='all',sourceKind='github';
let toastTimer;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cat=id=>categories.find(c=>c.id===id);
const source=id=>sources.find(s=>s.id===id);
const duration=s=>{s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const provenanceLabel=q=>({github:'GitHub 公开整理题',public:'其他公开样题',original:'原创补充题'})[q.provenance]||'来源未标注';
const difficulty=q=>['基础','进阶','挑战'][q.difficulty-1];
const modeName=mode=>({instant:'即时反馈',practice:'手动核对',exam:'限时模拟'})[mode]||'能力练习';
function sampleAdvice(category){const available=questions.filter(q=>q.category===category&&q.provenance==='github').length;return available<10?`该模块当前有 ${available} 道 GitHub 题，先复盘现有题目。样本较少，暂不据此判断能力高低。`:'本次题量较少，先补充 10 道专项题再判断。';}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3500);}
function setView(next){if(session&&view==='quiz'&&next!=='quiz'){captureTime();session.entered=null;}if(session&&view!=='quiz'&&next==='quiz')session.entered=Date.now();view=next;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===next);if(b.dataset.view===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.getElementById('breadcrumb').textContent=({home:'开始练习',quiz:'正在作答',report:'本次成绩',wrong:'本次错题',sources:'题库与来源'})[next];render();window.scrollTo(0,0);app.focus({preventScroll:true});}
function heading(title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">ABILITY PRACTICE</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function selectField(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function home(){
 const orig=questions.filter(q=>q.provenance==='original').length,pub=questions.filter(q=>q.provenance==='public').length,gh=questions.filter(q=>q.provenance==='github').length;
 app.innerHTML=heading('把练习，变成有方向的进步','选择一组题开始练习，完成后查看成绩、解析与下一步建议。',session?'<button class="btn secondary" data-action="resume">继续当前练习</button>':'')+`
 <div class="stats-strip"><div class="stat"><b>${gh}</b><span>道</span><small>GitHub 来源题 · 默认使用</small></div><div class="stat"><b>7</b><span>类</span><small>专项题型覆盖</small></div><div class="stat"><b>4</b><span>维</span><small>官方认知能力维度</small></div><div class="stat"><b>0</b><span>题</span><small>性格与自陈类题目</small></div></div>
 <div class="setup-layout"><section class="panel"><div class="panel-head"><h2>配置你的练习</h2><small>单选题 · 每题等权</small></div><div class="mode-tabs" role="group" aria-label="练习模式"><button data-mode="instant" class="${config.mode==='instant'?'active':''}" aria-pressed="${config.mode==='instant'}">即时反馈</button><button data-mode="practice" class="${config.mode==='practice'?'active':''}" aria-pressed="${config.mode==='practice'}">手动核对</button><button data-mode="exam" class="${config.mode==='exam'?'active':''}" aria-pressed="${config.mode==='exam'}">限时模拟</button></div>
 <form id="setup-form"><div class="form-grid">${selectField('训练模块','category',[['all','综合 · 按可用题型均衡抽题'],...categories.map(c=>[c.id,c.name])],config.category)}${selectField('题目数量','count',[['7','7 题 · 快速热身'],['14','14 题 · 日常练习'],['28','28 题 · 综合训练'],['35','35 题 · 完整模拟'],['all','当前筛选的全部题目']],config.count)}${selectField('训练难度','difficulty',[['','混合难度'],['1','基础'],['2','进阶'],['3','挑战']],config.difficulty)}${selectField('题目来源','provenance',[['github','GitHub 来源题（默认，无原创）'],['public','其他公开样题'],['original','原创补充题'],['','全部来源（含原创）']],config.provenance)}${config.mode==='exam'?`<label class="field">总限时（分钟）<input type="number" name="minutes" min="1" max="240" value="${config.minutes}" required></label>`:''}</div><div class="setup-action"><p>${config.mode==='exam'?'交卷后统一显示答案。计时结束自动提交，未答题计为未得分。':config.mode==='instant'?'选中答案即提交本题，立即显示对错、正确答案与解析。答案会锁定，看完后点击下一题。':'选好答案后点击“核对答案”，显示对错与解析。也可先做完再统一交卷。'}</p><button type="submit" class="btn primary">${session?'开始新一组练习':'开始练习'}</button></div><p class="small" id="pool-info" style="margin-top:13px"></p></form></section>
 <aside class="panel training-note"><div class="step-label">练习路径 / 01 · 02 · 03</div><h2>找到薄弱项，再有针对性地练</h2><div class="steps"><div class="step"><span class="step-num">01</span><div><b>先做一组综合练习</b><p>观察各模块的正确率和用时</p></div></div><div class="step"><span class="step-num">02</span><div><b>看懂每一道错题</b><p>区分读题、建模和计算问题</p></div></div><div class="step"><span class="step-num">03</span><div><b>用限时训练检验进步</b><p>逐步兼顾正确率与答题节奏</p></div></div></div><div class="note-rule">练习难度与时间为训练设置。模拟采用固定题数与总限时，不复刻北森 CATA 的自适应抽题与官方计分。</div></aside></div>
 <div class="section-title"><h2>按题型专项练习</h2><small>点选模块即可开始配置</small></div><div class="category-grid">${categories.map(c=>`<button class="category-card" data-category="${c.id}"><span class="category-icon" aria-hidden="true">${c.icon}</span><h3>${c.name}</h3><p>${githubBrief[c.id]||c.brief}</p><small><b>${questions.filter(q=>q.category===c.id&&q.provenance==='github').length} 道 GitHub 题</b> · ${c.dimension}</small></button>`).join('')}<div class="source-callout"><b>每道题都说明来源</b><p>${gh} 道 GitHub 来源题<br>${pub} 道其他公开样题<br>${orig} 道可选原创补充题</p><button class="text-link" data-view="sources" style="margin-top:11px">查看来源与收录标准</button></div></div>
 <p class="source-banner"><strong>题库透明：</strong>默认仅抽 GitHub 来源题，包含北森相关整理与通用能力补充；每题保留原题编号与链接。第三方题库未经北森官方认证。原创题需在来源筛选中手动选择。</p>`;
 const form=document.getElementById('setup-form');form.addEventListener('change',()=>{readConfig();updatePool();});form.addEventListener('submit',e=>{e.preventDefault();readConfig();start();});updatePool();
}
function readConfig(){const form=document.getElementById('setup-form');if(!form)return;const fd=new FormData(form);for(const key of ['category','count','difficulty','provenance'])if(fd.has(key))config[key]=fd.get(key);if(fd.has('minutes'))config.minutes=Number(fd.get('minutes'));}
function updatePool(){const pool=selectQuestions(questions,{...config,count:'all'});const chosen=Math.min(config.count==='all'?pool.length:Number(config.count),pool.length);document.getElementById('pool-info').textContent=`当前可选 ${pool.length} 题，本组将抽取 ${chosen} 题；组内不重复${chosen&&config.category==='all'?'，尽量均衡覆盖可用模块':''}。`;}
async function confirmAction(title,copy,button='确认'){const dialog=document.getElementById('confirm-dialog');document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-copy').textContent=copy;dialog.querySelector('[value="confirm"]').textContent=button;dialog.returnValue='';return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
async function start(explicit){
 const list=explicit||selectQuestions(questions,config);if(!list.length){toast('这个筛选组合没有题目，请调整难度或来源。');return;}
 if(config.mode==='exam'&&(!Number.isFinite(config.minutes)||config.minutes<1||config.minutes>240)){toast('限时请输入 1–240 分钟。');return;}
 if(session&&!await confirmAction('开始新练习？','当前未交卷的作答将结束。已提交的上一份成绩仍可查看。','开始新练习'))return;
 const now=Date.now();session={questions:list,answers:{},times:{},checked:new Set(),marked:new Set(),index:0,started:now,entered:now,mode:config.mode,deadline:config.mode==='exam'?now+config.minutes*60000:null};setView('quiz');
}
function render(){if(view==='home')home();else if(view==='quiz')quiz();else if(view==='report')reportView();else if(view==='wrong')wrongView();else if(view==='sources')sourcesView();document.getElementById('wrong-count').textContent=String(wrongIds.size);}
// 图形采用可访问的 SVG，标签说明与图形规格一致。
function svgFigure(spec){
 const common='viewBox="0 0 100 100" role="img"';let content='',label='';
 if(spec.kind==='arrow'){label=`箭头从向上方向顺时针旋转 ${spec.angle} 度`;content=`<g transform="rotate(${spec.angle} 50 50)"><path d="M50 18L73 43H59V80H41V43H27Z" fill="#31567f"/></g>`;}
 if(spec.kind==='dots'){label=`${spec.count} 个圆点`;for(let i=0;i<spec.count;i++){const col=i%4,row=Math.floor(i/4);content+=`<circle cx="${23+col*18}" cy="${26+row*22}" r="5.5" fill="#31567f"/>`;}}
 if(spec.kind==='grid'){label='四格图，按行读取为'+spec.cells.map(v=>v?'黑':'白').join('、');spec.cells.forEach((v,i)=>content+=`<rect x="${20+(i%2)*30}" y="${20+Math.floor(i/2)*30}" width="30" height="30" fill="${v?'#31567f':'#fff'}" stroke="#8a9cb4" stroke-width="1.5"/>`);}
 if(spec.kind==='move'){label=`九宫格黑点在第 ${spec.position+1} 格`;for(let i=0;i<9;i++)content+=`<rect x="${17+(i%3)*22}" y="${17+Math.floor(i/3)*22}" width="22" height="22" fill="white" stroke="#b3becf"/>`;content+=`<circle cx="${28+(spec.position%3)*22}" cy="${28+Math.floor(spec.position/3)*22}" r="6" fill="#31567f"/>`;}
 return `<svg ${common} aria-label="${esc(label)}">${content}</svg>`;
}
function spatialFigure(s){
 if(s.kind==='net'){const coords=[[1,0],[0,1],[1,1],[2,1],[1,2],[1,3]];return `<svg class="spatial-svg" viewBox="0 0 260 290" role="img" aria-label="十字形立方体展开图，上方 ${esc(s.labels[0])}；中排 ${esc(s.labels.slice(1,4).join('、'))}；中心下方 ${esc(s.labels[4])}；最下方 ${esc(s.labels[5])}">${coords.map(([x,y],i)=>`<rect x="${25+x*66}" y="${12+y*66}" width="66" height="66" fill="${i===2?'#e5edf8':'#f5f7fa'}" stroke="#6480a6" stroke-width="1.7"/><text x="${58+x*66}" y="${52+y*66}" text-anchor="middle" font-size="20" fill="#294c7b">${esc(s.labels[i])}</text>`).join('')}</svg>`;}
 if(s.kind==='cube'){return `<svg class="spatial-svg" viewBox="0 0 280 205" role="img" aria-label="六个外表面涂色的立方体，每条棱分为 ${s.n} 段"><path d="M65 67L140 25L215 67L140 110Z" fill="#d7e4f5" stroke="#4c719e"/><path d="M65 67L140 110V184L65 142Z" fill="#8da9cd" stroke="#4c719e"/><path d="M140 110L215 67V142L140 184Z" fill="#537ba9" stroke="#4c719e"/>${Array.from({length:s.n-1},(_,i)=>{const t=(i+1)/s.n;return `<path d="M${65+75*t} ${67+43*t}V${142+42*t}M65 ${67+75*t}L140 ${110+74*t}M${140+75*t} ${110-43*t}V${184-42*t}M140 ${110+74*t}L215 ${67+75*t}M${65+75*t} ${67-42*t}L${140+75*t} ${110-43*t}M${65+75*t} ${67+43*t}L${140+75*t} ${25+42*t}" fill="none" stroke="#4c719e" stroke-width=".8"/>`;}).join('')}<text x="140" y="202" text-anchor="middle" font-size="14" fill="#526d90">每条棱 ${s.n} 个小正方体</text></svg>`;}
 if(s.kind==='heights')return `<svg class="spatial-svg" viewBox="0 0 240 250" role="img" aria-label="高度表，行从上到下为 ${esc(s.heights.map(r=>r.join('、')).join('；'))}，观察方向从下向上">${s.heights.flatMap((r,y)=>r.map((v,x)=>`<rect x="${36+x*56}" y="${18+y*56}" width="56" height="56" fill="#edf2fa" stroke="#7a93b5"/><text x="${64+x*56}" y="${53+y*56}" text-anchor="middle" fill="#335882" font-size="22">${v}</text>`)).join('')}<path d="M120 224V195M110 207L120 195L130 207" stroke="#e96137" stroke-width="3" fill="none"/><text x="120" y="247" text-anchor="middle" font-size="14" fill="#526d90">从此方向观察</text></svg>`;
 return '';
}
function materials(q){return `${q.images?`<div class="source-images">${q.images.map(im=>`<div class="source-image-wrap">${imageContent(im)}<button class="text-link image-zoom-trigger" data-image-view="${esc(im.file)}">放大查看图片</button></div>`).join('')}</div>`:''}${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}${q.table?`<div class="small">${esc(q.table.caption)}</div><div class="data-table-wrap"><table class="data-table"><thead><tr>${q.table.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${q.table.rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${q.figures?`<div class="figures">${q.figures.map((f,i)=>`<div class="figure">${svgFigure(f)}<span>第 ${i+1} 幅</span></div>`).join('')}</div>`:''}${q.matrix?`<div style="display:grid;grid-template-columns:repeat(3,108px);gap:10px;max-width:100%;overflow-x:auto;margin-bottom:20px">${q.matrix.flat().map(f=>f?svgFigure(f):'<div style="display:grid;place-items:center;font-size:2rem;background:#f5f7fa;min-height:108px" aria-label="需要补全的图形">?</div>').join('')}</div>`:''}${q.spatial?spatialFigure(q.spatial):''}`;}
function imageContent(spec){const href=window.PRACTICE_IMAGES?.[spec.file]||spec.file;const crop=spec.crop||[0,0,spec.width,spec.height];const displayWidth=Math.min(580,Math.max(200,spec.width*1.8));return `<svg class="source-image ${spec.crop?'image-option':'image-material'}" viewBox="${crop.join(' ')}" role="img" aria-label="${esc(spec.alt||'原题图片')}" style="aspect-ratio:${crop[2]}/${crop[3]};--image-render-width:${displayWidth}px"><image href="${esc(href)}" x="0" y="0" width="${spec.width}" height="${spec.height}"/></svg>`;}
function optionContent(o){return typeof o==='object'?(o.kind==='image'?imageContent(o):svgFigure(o)):esc(o);}
function openSourceImage(file){const spec=questions.flatMap(q=>q.images||[]).find(im=>im.file===file);if(!spec)return;const dialog=document.getElementById('image-dialog'),width=Math.max(420,spec.width*1.6),height=width*spec.height/spec.width;document.getElementById('image-preview').innerHTML=imageContent(spec).replace('class="source-image image-material"',`class="source-image enlarged-image" style="width:${width}px;height:${height}px"`).replace(/ style="aspect-ratio:[^"]*"/,'');dialog.showModal();}
function sourceLine(q){const s=source(q.source);if(q.provenance==='original')return '来源：可选原创补充题；按官方能力维度设计。';return `来源：<a href="${esc(q.sourceUrl||s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>${q.sourceQuestionId?` · 原题编号 ${esc(q.sourceQuestionId)}`:''}<br>${esc(q.reviewNote||'第三方公开样题，实考真实性未认证；答案独立复核。')}`;}
function explanation(q,answer){const correct=answer===q.answer;return `<div class="explanation ${correct?'':'wrong'}" role="status" aria-live="polite" tabindex="-1"><h3>${correct?'回答正确':answer===undefined||answer===null?'本题未作答':'回答错误'} · 正确答案 ${'ABCDE'[q.answer]}</h3><p>${esc(q.explanation)}</p><div class="source-line">${sourceLine(q)}</div></div>`;}
function captureTime(){if(!session||session.entered===null)return;const now=Date.now(),q=session.questions[session.index];const end=session.deadline?Math.min(now,session.deadline):now;session.times[q.id]=(session.times[q.id]||0)+Math.max(0,(end-session.entered)/1000);session.entered=now;}
function quiz(){
 if(!session){setView('home');return;}const s=session,q=s.questions[s.index],checked=s.checked.has(q.id),a=s.answers[q.id];
 app.innerHTML=heading(modeName(s.mode),`${s.mode==='exam'?'提交后查看全部答案':s.mode==='instant'?'选择答案即显示对错与解析':'选好答案后点击核对'} · 本组 ${s.questions.length} 题`,'<button class="btn secondary" data-view="home">返回工作台</button>')+`<div class="quiz-layout"><section class="panel"><div class="quiz-meta">${badge(cat(q.category).name)}${badge(q.tag,'gray')}${badge(difficulty(q),'gray')}${badge(provenanceLabel(q),'orange')}<span class="small" style="margin-left:auto">第 ${s.index+1} / ${s.questions.length} 题</span></div>${materials(q)}<h2 class="question-stem">${esc(q.stem)}</h2><div class="options" role="group" aria-label="选择一个答案">${q.options.map((o,i)=>`<button class="option ${a===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&a===i&&i!==q.answer?'incorrect':''}" data-answer="${i}" aria-pressed="${a===i}" ${checked?'disabled':''}><span class="option-letter">${'ABCDE'[i]}</span><span class="option-text">${optionContent(o)}</span>${checked&&i===q.answer?'<span class="option-status">正确答案</span>':checked&&a===i?'<span class="option-status">你的答案</span>':''}</button>`).join('')}</div>${checked?explanation(q,a):''}<div class="quiz-actions"><button class="text-link" data-action="mark">${s.marked.has(q.id)?'取消标记':'标记，稍后再看'}</button><div class="button-row"><button class="btn secondary" data-action="prev" ${s.index===0?'disabled':''}>上一题</button>${s.mode==='practice'&&!checked?`<button class="btn dark" data-action="check" ${a===undefined?'disabled':''}>核对答案</button>`:''}<button class="btn primary" data-action="next">${s.index===s.questions.length-1?'交卷看成绩':'下一题'}</button></div></div><p class="small" style="margin-top:16px">键盘 A–E 选择答案；左右方向键切换题目。${s.mode==='instant'?'选中即提交，答案会锁定。':'已核对的答案会锁定。'}</p></section><aside class="quiz-side"><section class="panel"><h3>${s.deadline?'剩余时间':'本组已用时'}</h3><div class="timer" id="timer">${duration((s.deadline?s.deadline-Date.now():Date.now()-s.started)/1000)}</div><p class="small">${s.deadline?'时间到自动提交':'本模式不限制总时间'}</p></section><section class="panel palette-panel"><div class="panel-head" style="margin:0"><h3>答题卡</h3><small id="answered-count"></small></div><div class="progress"><span id="answer-progress"></span></div><div class="palette">${s.questions.map((item,i)=>`<button data-jump="${i}" class="${s.answers[item.id]!==undefined?'answered':''} ${s.marked.has(item.id)?'marked':''} ${i===s.index?'current':''}" aria-label="第 ${i+1} 题${s.answers[item.id]!==undefined?'，已答':'，未答'}${s.marked.has(item.id)?'，已标记':''}" ${i===s.index?'aria-current="true"':''}>${i+1}</button>`).join('')}</div><div class="legend"><span><i></i>已作答</span><span><i class="mark"></i>已标记</span></div><button class="btn secondary" data-action="submit" style="width:100%;margin-top:20px">提交练习</button></section><section class="panel side-help"><h3>这一题怎么练</h3><p class="small" style="margin-top:9px">${cat(q.category).tip}</p><p class="small" style="margin-top:12px">建议节奏：约 ${q.seconds} 秒/题，为训练参考。</p></section></aside></div>`;updateAnswered();
}
function updateAnswered(){if(!session)return;const n=Object.keys(session.answers).length;const label=document.getElementById('answered-count');if(label)label.textContent=`${n} / ${session.questions.length}`;const progress=document.getElementById('answer-progress');if(progress)progress.style.width=(n/session.questions.length*100)+'%';}
function jump(i){if(!session)return;captureTime();session.index=Math.max(0,Math.min(i,session.questions.length-1));quiz();}
async function submit(auto=false){if(!session)return;const n=session.questions.filter(q=>session.answers[q.id]===undefined).length;if(!auto&&!await confirmAction('提交本次练习？',n?`还有 ${n} 题未作答。未答题不计分，交卷后将显示解析与建议。`:'所有题目已作答，交卷后显示成绩、各模块表现与解析。','确认提交'))return;if(!session)return;captureTime();const elapsed=(Math.min(Date.now(),session.deadline||Date.now())-session.started)/1000;report=assess(session.questions,session.answers,session.times,elapsed);report.auto=auto;report.at=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});reportSession=session;report.rows.forEach(r=>{if(r.correct){wrongIds.delete(r.id);wrongAnswers.delete(r.id);}else{wrongIds.add(r.id);wrongAnswers.set(r.id,r.answer);}});session=null;setView('report');if(auto)toast('时间已到，已自动提交本次模拟。');}
function reportView(){
 if(!report){app.innerHTML=heading('本次成绩','完成一组题目后，这里会显示正确率、练习分数与指导建议。')+'<div class="empty"><h2>还没有提交过练习</h2><p>先完成一组综合题，了解自己的起点。</p><button class="btn primary" data-view="home">开始练习</button></div>';return;}
 const r=report;
 const advice=r.dimensions.filter(d=>d.answered>0).sort((a,b)=>a.accuracy-b.accuracy).slice(0,2);
 app.innerHTML=heading('这次练习，有了清晰的反馈',`${r.at} · ${modeName(reportSession.mode)} · ${r.total} 题`, '<div class="button-row"><button class="btn secondary" data-action="export">导出报告</button><button class="btn primary" data-action="again">再练一组</button></div>')+`${r.auto?'<div class="session-notice">限时结束，系统已自动交卷；未答题按未得分统计。</div>':''}<div class="report-top"><section class="panel score-panel"><div class="score-ring" style="--score:${r.score}"><b>${r.score}</b></div><div><strong>练习分数 / 100</strong><p>每题等权 · 答错不倒扣<br>答对 ${r.correct} / ${r.total} 题</p></div></section><section class="panel report-metrics"><div><b>${r.accuracy}%</b><p>正确率（含未答题）</p></div><div><b>${r.completion}%</b><p>完成率 · ${r.answered} 题已答</p></div><div><b>${duration(r.elapsed)}</b><p>本组总用时</p></div></section></div><div class="report-layout"><section class="panel"><div class="panel-head"><h2>各题型表现</h2><small>本次样本，不是能力排名</small></div>${r.dimensions.map(d=>`<div class="dimension-row"><span>${cat(d.category).name}</span><div class="progress"><span style="width:${d.accuracy}%;background:${d.accuracy<60?'#d98562':'#3c699c'}"></span></div><b>${d.accuracy}%</b><small>答对 ${d.correct}/${d.total} · 未答 ${d.skipped} · 均用时 ${Math.round(d.averageSeconds)} 秒${d.total<3?' · 样本较少':''}</small></div>`).join('')}<div class="info-box" style="margin-bottom:0">分数 = 答对题数 ÷ 总题数 × 100；正确率使用相同分母。已答题正确率为 ${r.answeredAccuracy}%，答错 ${r.incorrect} 题，未答 ${r.skipped} 题。</div></section><section class="panel"><h2>下一步怎么练</h2>${r.answered===0?'<div class="advice-item"><h3>先完成作答，才能形成反馈</h3><p>本次没有已答题，无法判断薄弱类型。先做 7–14 道不限时练习，认真提交答案。</p></div>':advice.map(d=>`<div class="advice-item"><h3>${d.total<3?'增加样本：':d.accuracy<70?'优先巩固：':'继续提升：'}${cat(d.category).name}</h3><p>${d.total<3?sampleAdvice(d.category):cat(d.category).tip}</p><button class="text-link" data-train="${d.category}" style="margin-top:9px">配置这个模块的专项练习</button></div>`).join('')}${r.skipped?`<div class="advice-item"><h3>提高完成度：还有 ${r.skipped} 题未答</h3><p>${reportSession.mode==='exam'?'下一次遇到暂时无思路的题，先标记继续，把最后的时间留给回看。':'先按答题卡补齐遗漏，再比较正确率；未答不代表不会。'}</p></div>`:''}<div class="advice-item"><h3>${r.dimensions.some(d=>d.slow>0)?'把准确率与速度分开练':'让方法稳定下来'}</h3><p>${r.dimensions.some(d=>d.slow>0)?'部分题用时超过训练参考。先不限时练到能解释解法，再逐步缩短作答时间；参考时长不代表官方限制。':r.accuracy>=80?'本次整体正确率较高，可以换一组混合难度题并尝试限时。单次成绩不代表正式测评结果。':'复盘每个错误是材料理解、规则识别还是运算失误，再做同类题验证方法。'}</p></div></section></div><div class="report-reviews"><div class="section-title"><h2>逐题解析</h2><small>展开可查看你的答案和正确答案</small></div><div class="review-list">${reportSession.questions.map((q,i)=>reviewCard(q,reportSession.answers[q.id],i+1)).join('')}</div></div>`;
}
function reviewCard(q,a,i){const correct=a===q.answer;return `<div class="review-card"><details><summary>${badge(correct?'答对':a===undefined||a===null?'未答':'答错',correct?'green':'orange')}${esc(i?i+'. ':'')}${esc(cat(q.category).name)} · ${esc(q.stem)}</summary><div style="margin-top:18px">${materials(q)}<div class="options">${q.options.map((o,j)=>`<div class="option ${j===q.answer?'correct':''} ${j===a&&j!==q.answer?'incorrect':''}"><span class="option-letter">${'ABCDE'[j]}</span><span class="option-text">${optionContent(o)}</span>${j===a?'<span class="option-status">你的答案</span>':''}</div>`).join('')}</div>${explanation(q,a)}</div></details></div>`;}
function wrongView(){const list=questions.filter(q=>wrongIds.has(q.id));app.innerHTML=heading('把错题练明白',`${list.length} 道本会话错题与未答题 · 重做答对后从列表移除`,list.length?'<button class="btn primary" data-action="retry-wrong">重练这组错题</button>':'')+`<p class="small" style="margin-bottom:20px">错题来自本页面会话中已提交的练习，刷新后清空。可从本次成绩导出报告留存。</p>`+(list.length?`<div class="review-list">${list.map((q,i)=>reviewCard(q,wrongAnswers.get(q.id),i+1)).join('')}</div>`:'<div class="empty"><h2>这里暂时没有错题</h2><p>提交练习后，答错和未答的题会出现在这里。</p><button class="btn primary" data-view="home">开始练习</button></div>');}
function sourcesView(){
 app.innerHTML=heading('题库与来源','先确认出处，再相信题目。每道题都可以追溯到收录说明。')+`<div class="info-box" style="margin-top:0"><b>收录结果：${questions.filter(q=>q.provenance==='github').length} 道 GitHub 来源题，默认不抽原创。</b><br>GitHub 题由北森相关整理题与通用能力补充组成。仅选条件完整、答案可复核的题目，每题可查看原题编号和固定提交链接；原题条件与选项保留，解析经复核。空间类目前仅 2 题，综合组抽完该类后会分配给其他模块。本工具已获北森官方认证的实考原题为 0 题。另有 ${questions.filter(q=>q.provenance==='public').length} 道其他公开样题、${questions.filter(q=>q.provenance==='original').length} 道可选原创补充题。排除人格、兴趣、价值观、动机及无统一客观答案的自陈问卷；仅训练可判分的认知能力题。</div><div class="section-title"><h2>资料核查记录</h2><small>核查日期：2026-10-02</small></div><div class="source-list">${sources.map(s=>`<article class="source-item">${badge(s.kind,s.id==='original'?'gray':s.id.startsWith('public')?'orange':'')}<h3>${esc(s.title)}</h3><p>${esc(s.note)}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">查看原始资料</a>`:''}</article>`).join('')}</div><div class="section-title"><h2>浏览题库</h2><small>题库列表不提前展示答案</small></div><div class="filter-row"><label>模块 <select id="bank-category">${[['all','全部模块'],...categories.map(c=>[c.id,c.name])].map(([id,name])=>`<option value="${id}" ${sourceCategory===id?'selected':''}>${name}</option>`).join('')}</select></label><label>来源 <select id="bank-kind"><option value="" ${sourceKind===''?'selected':''}>全部来源</option><option value="github" ${sourceKind==='github'?'selected':''}>GitHub 来源题</option><option value="public" ${sourceKind==='public'?'selected':''}>其他公开样题</option><option value="original" ${sourceKind==='original'?'selected':''}>原创补充题</option></select></label><label>关键词 <input id="bank-search" type="search" value="${esc(search)}" placeholder="题干或考点" aria-label="搜索题干或考点"></label></div><div id="bank-results"></div>`;
 document.getElementById('bank-category').addEventListener('change',e=>{sourceCategory=e.target.value;renderBankResults();});document.getElementById('bank-kind').addEventListener('change',e=>{sourceKind=e.target.value;renderBankResults();});document.getElementById('bank-search').addEventListener('input',e=>{search=e.target.value;renderBankResults();});renderBankResults();
}
function renderBankResults(){const list=questions.filter(q=>(sourceCategory==='all'||q.category===sourceCategory)&&(!sourceKind||q.provenance===sourceKind)&&(!search||[q.stem,q.tag,q.passage||''].join(' ').includes(search)));document.getElementById('bank-results').innerHTML=`<p class="bank-count">找到 ${list.length} 道题 · 难度为未经常模校准的训练标签</p><div class="bank-list">${list.map(q=>`<div class="bank-item">${badge(cat(q.category).name)}<div class="title"><p>${esc(q.stem)}</p><small>${q.id} · ${q.tag} · ${difficulty(q)} · ${provenanceLabel(q)}</small></div><button class="btn secondary" data-single="${q.id}">练这题</button></div>`).join('')}</div>`;}
function exportReport(){if(!report)return;const data={tool:'北森测评练习（独立工具）',date:report.at,practiceMode:reportSession.mode,scoring:'答对题数/总题数×100；答错和未答不得分，不倒扣；不是官方分数或百分位',summary:report,review:reportSession.questions.map(q=>({id:q.id,module:cat(q.category).name,tag:q.tag,stem:q.stem,passage:q.passage||null,table:q.table||null,figures:q.figures||q.matrix||q.spatial||null,options:q.options,yourAnswer:reportSession.answers[q.id]??null,correctAnswer:q.answer,explanation:q.explanation,provenance:q.provenance,source:source(q.source),sourceQuestionId:q.sourceQuestionId||null,sourceUrl:q.sourceUrl||null,images:q.images||null}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='北森练习报告-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('报告已导出，包含成绩、答案和解析。');}
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a.brand');if(!el||el.disabled)return;
 if(el.dataset.imageView){openSourceImage(el.dataset.imageView);return;}
 if(el.dataset.action==='close-image'){document.getElementById('image-dialog').close();return;}
 if(el.matches('a.brand')){e.preventDefault();setView('home');return;}
 if(el.dataset.view){setView(el.dataset.view);return;}
 if(el.dataset.mode){readConfig();config.mode=el.dataset.mode;home();return;}
 if(el.dataset.category||el.dataset.train){config.category=el.dataset.category||el.dataset.train;config.mode=config.mode==='exam'?'instant':config.mode;config.provenance='github';config.difficulty='';config.count='14';setView('home');document.getElementById('setup-form').scrollIntoView({block:'center'});return;}
 if(el.dataset.single){config.mode=config.mode==='exam'?'instant':config.mode;await start([questions.find(q=>q.id===el.dataset.single)]);return;}
 if(el.dataset.answer!==undefined&&session){const q=session.questions[session.index];if(session.checked.has(q.id))return;session.answers[q.id]=Number(el.dataset.answer);if(session.mode==='instant')session.checked.add(q.id);quiz();if(session.mode==='instant'){const feedback=app.querySelector('.explanation');feedback?.scrollIntoView({block:'nearest',behavior:'auto'});feedback?.focus({preventScroll:true});}return;}
 if(el.dataset.jump!==undefined){jump(Number(el.dataset.jump));return;}
 const action=el.dataset.action;
 if(action==='resume'){setView('quiz');return;}
 if(action==='check'&&session){const q=session.questions[session.index];if(session.answers[q.id]===undefined)return;session.checked.add(q.id);quiz();return;}
 if(action==='mark'&&session){const id=session.questions[session.index].id;session.marked.has(id)?session.marked.delete(id):session.marked.add(id);quiz();return;}
 if(action==='prev'&&session){jump(session.index-1);return;}
 if(action==='next'&&session){session.index===session.questions.length-1?await submit():jump(session.index+1);return;}
 if(action==='submit'){await submit();return;}
 if(action==='export'){exportReport();return;}
 if(action==='again'){await start();return;}
 if(action==='retry-wrong'){config.mode=config.mode==='exam'?'instant':config.mode;await start(questions.filter(q=>wrongIds.has(q.id)));return;}
});
document.addEventListener('keydown',e=>{if(view!=='quiz'||!session||document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const key=e.key.toLowerCase();if(['a','b','c','d','e'].includes(key)){const btn=document.querySelector(`[data-answer="${key.charCodeAt(0)-97}"]`);if(btn&&!btn.disabled){e.preventDefault();btn.click();}}if(e.key==='ArrowLeft'){e.preventDefault();jump(session.index-1);}if(e.key==='ArrowRight'){e.preventDefault();jump(session.index+1);}});
function tick(){if(!session)return;const remaining=session.deadline?session.deadline-Date.now():Date.now()-session.started;const el=document.getElementById('timer');if(el){el.textContent=duration(remaining/1000);el.classList.toggle('warning',!!session.deadline&&remaining<60000);}if(session.deadline&&remaining<=0){const d=document.getElementById('confirm-dialog');if(d.open)d.close('cancel');const im=document.getElementById('image-dialog');if(im.open)im.close();void submit(true);}}
setInterval(tick,1000);document.addEventListener('visibilitychange',tick);window.addEventListener('beforeunload',e=>{if(session&&Object.keys(session.answers).length){e.preventDefault();e.returnValue='';}});
const modelContext=document.modelContext;
if(modelContext?.registerTool){
 const lifecycle=new AbortController();
 const definitions=[{
  name:'configure_practice',title:'配置能力练习',description:'设置题型、数量与模式并显示配置界面；不提交作答，不结束当前练习。',
  inputSchema:{type:'object',properties:{category:{type:'string',enum:['all',...categories.map(c=>c.id)]},count:{type:'integer',enum:[7,14,28,35]},mode:{type:'string',enum:['instant','practice','exam']},minutes:{type:'integer',minimum:1,maximum:240}},additionalProperties:false},
  annotations:{readOnlyHint:false,untrustedContentHint:false},
  execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('配置必须为对象');if(Object.keys(input).some(k=>!['category','count','mode','minutes'].includes(k)))throw Error('配置包含未知字段');if(input.category!==undefined&&!['all',...categories.map(c=>c.id)].includes(input.category))throw Error('无效模块');if(input.count!==undefined&&![7,14,28,35].includes(input.count))throw Error('无效题量');if(input.mode!==undefined&&!['instant','practice','exam'].includes(input.mode))throw Error('无效模式');if(input.minutes!==undefined&&(!Number.isInteger(input.minutes)||input.minutes<1||input.minutes>240))throw Error('无效限时');config={...config,...input,count:String(input.count||config.count)};setView('home');return {configured:true,category:config.category,count:config.count,mode:config.mode,minutes:config.minutes,activePracticeRetained:!!session};}
 },{
  name:'read_practice_result',title:'读取本次练习结果',description:'读取已提交的本次练习分数、正确率和模块统计；没有交卷时返回结果未就绪。',
  inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},
  execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('此工具只接受空对象');return report?{ready:true,score:report.score,accuracy:report.accuracy,total:report.total,answered:report.answered,correct:report.correct,skipped:report.skipped,dimensions:report.dimensions}: {ready:false};}
 }];
 for(const definition of definitions){try{Promise.resolve(modelContext.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
setView('home');
})();
